/**
 * In-app auto-update (Tauri desktop only).
 *
 * The updater endpoint is the GitHub release feed (latest.json, generated by
 * tauri-action). Updates are signature-verified against the pubkey baked into
 * the app, so a clinic machine can update itself over any internet connection
 * without re-downloading the installer from the releases page.
 *
 * Flow: check() on a schedule → if an update exists, surface a non-blocking
 * banner (never force an interrupt mid-consultation) → user clicks
 * "Download update" → progress → NSIS installer runs in passive mode and the
 * app relaunches. On Windows the install step exits the app automatically,
 * so save pending DB writes first via the offline flush.
 *
 * ── Unattended installation ────────────────────────────────────────────────
 * Waiting for that click meant a clinic machine could sit on an old version for
 * weeks: nobody opens Settings → About, and a banner is easy to ignore for
 * good. So the default (Settings → About → "Install updates automatically",
 * the `update_mode` setting) is now unattended. The update is downloaded in the
 * background the moment it is found, then installed at the first *safe*
 * moment — the window has been in the background for 30 s, or nothing has been
 * touched for ten minutes. An open modal is never a safe moment, so an
 * unfinished form cannot be thrown away mid-edit, and pending DB writes are
 * flushed before the installer starts.
 *
 * The client itself defaults to "ask" — nothing downloads or restarts until the
 * app shell has read the stored preference — and `update_mode = "ask"` restores
 * the old behaviour exactly: check, banner, install on click. Flipping the
 * switch back and forth never loses a download that is already staged.
 *
 * ── Why there is a second path ─────────────────────────────────────────────
 * The plugin's check() is a black box that either works or throws. A single
 * failed install (NSIS registry entry missing after a per-machine install, a
 * proxy that strips the GitHub redirect, a WebView whose shell cache predates
 * the release) used to leave the machine reporting "You're on the latest
 * version" forever — the "stuck at 1.4.10" reports. So every check now also
 * reads the release feed directly and compares it with the running build:
 *
 *   - plugin finds an update      → mode "installer" (self-install, signed)
 *   - plugin fails/returns none,
 *     but the feed is newer       → mode "manual" (open the installer URL)
 *   - both fail                   → recorded in diagnostics, shown in Settings
 *
 * Failures are never silent any more: `subscribeToDiagnostics` carries the
 * last error, the last check time, and whether the feed is reachable.
 */

import { check, type Update } from "@tauri-apps/plugin-updater";
import { relaunch } from "@tauri-apps/plugin-process";
import { isTauriDesktop, flushDatabase, flushDatabaseAndWait } from "@/offline/activate";
import { saveUpdateNotesForNextBoot } from "@/components/update-applied-banner";
import { openExternalUrl } from "@/lib/open-external";
import { isNewer } from "@/lib/version";

export interface UpdateState {
  /** Update metadata available from the feed. */
  version: string;
  notes: string;
  /**
   * "available" → found but not downloaded; "downloading" → progress 0..1;
   * "staged" → downloaded, waiting for a safe moment to install;
   * "ready" → installing and restarting.
   */
  phase: "available" | "downloading" | "staged" | "ready";
  /** 0..1 download progress; only meaningful while downloading. */
  progress: number;
  /**
   * How this update can be applied:
   *  - "installer": the signed in-app updater can download and install it.
   *  - "manual": self-install is unavailable on this machine, so the UI
   *    offers the installer download for the user to run once.
   *  - "repair": the binary is already current (the plugin reports no update)
   *    while the running UI is older — a stale service-worker shell. The UI
   *    offers "Repair cached files" instead of another download.
   */
  mode: "installer" | "manual" | "repair";
  /** Direct installer URL for "manual" mode (release asset or release page). */
  downloadUrl?: string;
}

export interface UpdateDiagnostics {
  /** When the last check completed (ms epoch), or null if none has run. */
  lastCheckedAt: number | null;
  /** Human-readable reason the last check could not offer a self-install. */
  lastError: string | null;
  /** Version advertised by the release feed, even if self-install is broken. */
  feedVersion: string | null;
  /** True when the signed in-app updater is usable on this machine. */
  selfInstall: boolean;
}

/**
 * How this machine applies updates (Settings → About).
 *
 * - "auto": download as soon as an update is found, install it at the first
 *   safe moment — no click. The default.
 * - "ask": check, tell the user, install only when they click.
 */
export type UpdateMode = "auto" | "ask";

type Listener = (state: UpdateState | null) => void;
type DiagnosticsListener = (diag: UpdateDiagnostics) => void;

let listeners = new Set<Listener>();
let diagnosticsListeners = new Set<DiagnosticsListener>();
let state: UpdateState | null = null;
let diagnostics: UpdateDiagnostics = {
  lastCheckedAt: null,
  lastError: null,
  feedVersion: null,
  selfInstall: true,
};
let checkTimer: number | null = null;
/**
 * How this machine applies updates — set from Settings → About.
 *
 * Defaults to the non-destructive mode: nothing downloads or restarts until
 * the app shell has read the stored preference and called `setUpdateMode` (a
 * fresh install stores "auto"). A build that forgets to wire the setting asks
 * instead of restarting itself.
 */
let updateMode: UpdateMode = "ask";
/** A downloaded package, held until a safe moment to install it. */
let staged: Update | null = null;
/** In-flight background download (dedupes the hourly check and the toggle). */
let backgroundDownload: Promise<void> | null = null;
/** Last pointer/keyboard/wheel input, ms epoch — the idle clock. */
let lastInteractionAt = Date.now();
/** When the window went to the background, or null while it is on screen. */
let hiddenSince: number | null = null;
let applyTimer: number | null = null;

/**
 * The release feed the Tauri updater reads is a release *asset*, and GitHub
 * serves release assets without CORS headers — a webview `fetch` of it is
 * blocked. The REST API returns the same release (version, notes, installer
 * URLs) with `access-control-allow-origin: *`, so the fallback probe uses it.
 * Unauthenticated, 60 requests/hour: one check per hour is far inside that.
 */
const FEED_URL = "https://api.github.com/repos/azshifat007/Dental-Canvas/releases/latest";
const RELEASES_PAGE = "https://github.com/azshifat007/Dental-Canvas/releases/latest";

/** Notify React subscribers (the settings card / banner). */
function emit(next: UpdateState | null): void {
  state = next;
  for (const l of listeners) l(state);
}

function emitDiagnostics(patch: Partial<UpdateDiagnostics>): void {
  diagnostics = { ...diagnostics, ...patch };
  for (const l of diagnosticsListeners) l(diagnostics);
}

export function subscribeToUpdates(listener: Listener): () => void {
  listeners.add(listener);
  listener(state);
  return () => listeners.delete(listener);
}

export function subscribeToDiagnostics(listener: DiagnosticsListener): () => void {
  diagnosticsListeners.add(listener);
  listener(diagnostics);
  return () => diagnosticsListeners.delete(listener);
}

export function getUpdateState(): UpdateState | null {
  return state;
}

export function getUpdateDiagnostics(): UpdateDiagnostics {
  return diagnostics;
}

export function isUpdateSupported(): boolean {
  return isTauriDesktop();
}

/** The release page — always valid, even when every automated path fails. */
export function releasesPageUrl(): string {
  return RELEASES_PAGE;
}

// ── Release feed (direct) ─────────────────────────────────────────────────

interface FeedAsset {
  name?: string;
  browser_download_url?: string;
}
interface Feed {
  tag_name?: string;
  body?: string;
  html_url?: string;
  assets?: FeedAsset[];
}

/**
 * Read the newest published release from the GitHub API.
 *
 * This is the same release the Tauri updater reads, fetched in the webview
 * instead of Rust. Nothing here is installed automatically — it only tells the
 * UI which version exists and where the installer lives — so no signature is
 * involved, and it works on machines where the plugin path is broken.
 * Returns null when offline, rate-limited, or unparseable.
 */
async function fetchFeed(): Promise<Feed | null> {
  try {
    const res = await fetch(FEED_URL, {
      cache: "no-store",
      headers: { Accept: "application/vnd.github+json" },
      signal: AbortSignal.timeout(10_000),
    });
    if (!res.ok) return null;
    return (await res.json()) as Feed;
  } catch {
    return null;
  }
}

/** Pick the installer URL for this OS from the release's assets. */
function pickDownloadUrl(feed: Feed): string {
  const assets = (feed.assets ?? []).filter(
    (a): a is { name: string; browser_download_url: string } =>
      Boolean(a.name && a.browser_download_url),
  );
  const patterns = /windows/i.test(navigator.userAgent)
    ? [/x64-setup\.exe$/i, /setup\.exe$/i]
    : /mac/i.test(navigator.userAgent)
      ? [/\.dmg$/i]
      : [/\.AppImage$/i, /\.deb$/i];
  for (const pattern of patterns) {
    const hit = assets.find((a) => pattern.test(a.name));
    if (hit) return hit.browser_download_url;
  }
  // Any installer beats nothing; the release page lists them all.
  return feed.html_url || RELEASES_PAGE;
}

function errorMessage(err: unknown): string {
  if (err instanceof Error && err.message) return err.message;
  const text = String(err ?? "").trim();
  return text || "unknown error";
}

// ── Checking ──────────────────────────────────────────────────────────────

let checking: Promise<string | null> | null = null;

/**
 * Query the update feed once. Safe to call repeatedly: calls are deduplicated
 * and the hourly timer lives in `startUpdatePoller`.
 *
 * Returns the newer version if one is known, else null.
 */
export function checkForUpdates(): Promise<string | null> {
  if (!isUpdateSupported()) return Promise.resolve(null);
  if (checking) return checking;
  checking = (async () => {
    // An update that is already downloaded (or downloading) is not up for
    // re-decision: re-running the check would overwrite the staged state the
    // installer is waiting on, and the next hourly check would then never
    // install it.
    if (staged || state?.phase === "downloading") return state?.version ?? null;

    let pluginError: string | null = null;
    let update: Update | null = null;

    try {
      update = await check({ timeout: 15_000 });
    } catch (err) {
      pluginError = errorMessage(err);
    }

    if (update) {
      emit({
        version: update.version,
        notes: update.body ?? "",
        phase: "available",
        progress: 0,
        mode: "installer",
      });
      emitDiagnostics({
        lastCheckedAt: Date.now(),
        lastError: null,
        feedVersion: update.version,
        selfInstall: true,
      });
      // Unattended machines download straight away; the install itself waits
      // for a safe moment (see applyStagedUpdateIfSafe).
      if (updateMode === "auto") void beginBackgroundDownload(update);
      return update.version;
    }

    // Plugin says "nothing" or failed. Ask the feed directly: a newer version
    // there means this machine cannot self-install but MUST still tell the
    // user an update exists (and where to get it).
    const feed = await fetchFeed();
    const feedVersion = (feed?.tag_name ?? "").replace(/^v/i, "") || null;
    const selfInstall = pluginError === null;
    emitDiagnostics({
      lastCheckedAt: Date.now(),
      lastError: pluginError,
      feedVersion,
      selfInstall,
    });

    if (feedVersion && isNewer(feedVersion, __APP_VERSION__)) {
      // A clean "no update" from the plugin means the BINARY is already at
      // (or beyond) the feed version while this page is older: the update was
      // installed but the UI is still served from a stale shell cache. That is
      // the "stuck on an old version" machine — repairing the cache is the fix,
      // re-installing the same version is not.
      emit({
        version: feedVersion,
        notes: (feed?.body ?? "").trim(),
        phase: "available",
        progress: 0,
        mode: pluginError === null ? "repair" : "manual",
        downloadUrl: pickDownloadUrl(feed as Feed),
      });
      return feedVersion;
    }

    return null;
  })();
  return checking.finally(() => {
    checking = null;
  });
}

// ── Unattended installation ───────────────────────────────────────────────

/**
 * How long the app must be left alone before a staged update installs itself.
 *
 * Ten minutes of no input is a consultation room with nobody at the keyboard;
 * thirty seconds in the background is a window the user has walked away from.
 * Either is long enough that the restart lands between appointments instead of
 * in the middle of one.
 */
export const AUTO_INSTALL_IDLE_MS = 10 * 60 * 1000;
export const AUTO_INSTALL_HIDDEN_MS = 30 * 1000;

/** How often a staged update re-checks whether the moment has come. */
const AUTO_INSTALL_POLL_MS = 30 * 1000;

export interface AutoApplyContext {
  now: number;
  /** Last pointer/keyboard/wheel input, ms epoch. */
  lastInteractionAt: number;
  /** When the window went to the background, or null while it is on screen. */
  hiddenSince: number | null;
  /** A modal is open — the user may have an unfinished form on screen. */
  dialogOpen: boolean;
}

/**
 * Is this a moment where restarting the app costs the user nothing?
 *
 * Pure so the ruling is testable and stated in one place: an open modal always
 * says no, otherwise the app must have been untouched for ten minutes or the
 * window in the background for thirty seconds.
 */
export function shouldAutoApply(ctx: AutoApplyContext): boolean {
  if (ctx.dialogOpen) return false;
  if (ctx.hiddenSince !== null && ctx.now - ctx.hiddenSince >= AUTO_INSTALL_HIDDEN_MS) return true;
  return ctx.now - ctx.lastInteractionAt >= AUTO_INSTALL_IDLE_MS;
}

/** The live inputs `shouldAutoApply` rules on. */
function liveContext(): AutoApplyContext {
  const doc = typeof document === "undefined" ? null : document;
  if (doc && hiddenSince === null && doc.visibilityState === "hidden") hiddenSince = Date.now();
  return {
    now: Date.now(),
    lastInteractionAt,
    hiddenSince,
    // Radix dialogs set role="dialog"; the setup wizard is marked the same way.
    dialogOpen: Boolean(doc?.querySelector('[role="dialog"], [aria-modal="true"]')),
  };
}

/**
 * Install the package downloaded by `beginBackgroundDownload`. Returns false
 * when nothing is staged (the caller then downloads it the ordinary way).
 *
 * On Windows the NSIS installer exits this process, so everything that must
 * survive — the doctor's data, the changelog for the post-update banner — is
 * written before `install()` is called.
 */
export async function installStagedUpdate(): Promise<boolean> {
  const update = staged;
  if (!update) return false;
  staged = null;
  const notes = state?.notes ?? "";
  // Record the attempt before anything can kill the process: the next boot
  // uses it to tell "installed" from "the installer never ran".
  markPendingInstall(__APP_VERSION__, update.version);
  // Windows hard-exits this process the instant the installer is launched, so
  // the pending writes must be on disk *now* — not a fire-and-forget message.
  await flushDatabaseAndWait();
  saveUpdateNotesForNextBoot(update.version, notes);
  emit({ version: update.version, notes, phase: "ready", progress: 1, mode: "installer" });
  try {
    // restartAfterInstall: true is what makes NSIS receive `/R` (and `/ARGS`)
    // and start the app again on a new version. Stated explicitly because the
    // whole "the window never comes back" failure hinges on it.
    await update.install({ restartAfterInstall: true });
  } catch (err) {
    // The installer could not even be launched (SmartScreen, antivirus, a
    // declined elevation prompt). The exe was not replaced: put the staged
    // package back so the user can retry, and say what happened.
    clearPendingInstall();
    staged = update;
    emit({ version: update.version, notes, phase: "staged", progress: 1, mode: "installer" });
    emitDiagnostics({ lastError: `the installer could not start: ${errorMessage(err)}` });
    throw err;
  }
  // Windows has already ended this process above (the plugin calls exit(0) as
  // soon as the installer is spawned). macOS and Linux swap the files under a
  // live process, so only they need an explicit relaunch.
  if (!isWindows()) await relaunch();
  return true;
}

/**
 * Apply a staged update when — and only when — the moment is safe. Called by
 * the watcher timer and right after a download finishes. Returns true when the
 * install was started.
 */
export async function applyStagedUpdateIfSafe(): Promise<boolean> {
  // The staged handle — not the advertised state — is what decides: the check
  // that survives it may have re-advertised the version.
  if (!staged) return false;
  if (updateMode !== "auto") return false;
  if (!shouldAutoApply(liveContext())) return false;
  try {
    return await installStagedUpdate();
  } catch (err) {
    // A failed automatic install must not leave the app promising an update it
    // cannot apply: fall back to the one-time installer download and say why.
    emitDiagnostics({ lastError: `automatic install failed: ${errorMessage(err)}` });
    emit(state ? { ...state, phase: "available", progress: 0, mode: "manual" } : null);
    return false;
  }
}

/**
 * Download the pending update in the background, then install it as soon as
 * the app is left alone. Failures are recorded, never fatal: the update stays
 * advertised and the banner/card can still offer it by hand.
 */
async function beginBackgroundDownload(handle?: Update): Promise<void> {
  if (backgroundDownload || staged) return;
  const current = state;
  if (!current || current.mode !== "installer") return;
  const run = (async () => {
    const update = handle ?? (await check({ timeout: 15_000 }));
    if (!update) return;
    emit({ ...current, phase: "downloading", progress: 0 });
    let total = 0;
    await update.download((event) => {
      switch (event.event) {
        case "Started":
          total = event.data.contentLength ?? 0;
          break;
        case "Progress":
          if (total > 0) {
            emit({
              ...(state ?? current),
              phase: "downloading",
              progress: Math.min(0.99, ((state?.progress ?? 0) * total + event.data.chunkLength) / total),
            });
          }
          break;
        case "Finished":
          break;
      }
    });
    staged = update;
    emit({ version: update.version, notes: current.notes, phase: "staged", progress: 1, mode: "installer" });
    await applyStagedUpdateIfSafe();
  })();
  backgroundDownload = run;
  try {
    await run;
  } catch (err) {
    emitDiagnostics({ lastError: `background download failed: ${errorMessage(err)}` });
    if (state?.phase === "downloading") emit({ ...state, phase: "available", progress: 0 });
  } finally {
    backgroundDownload = null;
  }
}

/**
 * Set how this machine applies updates (Settings → About). Switching to
 * "auto" while an update is already on offer starts its download right away
 * instead of waiting up to an hour for the next check.
 */
export function setUpdateMode(mode: UpdateMode): void {
  updateMode = mode;
  if (mode !== "auto") return;
  if (state?.phase === "available" && state.mode === "installer") void beginBackgroundDownload();
  else void applyStagedUpdateIfSafe();
}

export function getUpdateMode(): UpdateMode {
  return updateMode;
}

/**
 * Watch for input, background the window and apply a staged update when the
 * moment is safe. Returns a cleanup function; never runs outside Tauri desktop
 * (the poller calls it).
 */
function watchForSafeMoment(): () => void {
  lastInteractionAt = Date.now();
  hiddenSince = document.visibilityState === "hidden" ? Date.now() : null;
  const noteInteraction = () => {
    lastInteractionAt = Date.now();
    if (document.visibilityState === "visible") hiddenSince = null;
  };
  const onVisibility = () => {
    hiddenSince = document.visibilityState === "hidden" ? Date.now() : null;
  };
  window.addEventListener("pointerdown", noteInteraction, { passive: true, capture: true });
  window.addEventListener("keydown", noteInteraction, { passive: true, capture: true });
  window.addEventListener("wheel", noteInteraction, { passive: true, capture: true });
  document.addEventListener("visibilitychange", onVisibility);
  applyTimer = window.setInterval(() => void applyStagedUpdateIfSafe(), AUTO_INSTALL_POLL_MS);
  return () => {
    window.removeEventListener("pointerdown", noteInteraction, { capture: true });
    window.removeEventListener("keydown", noteInteraction, { capture: true });
    window.removeEventListener("wheel", noteInteraction, { capture: true });
    document.removeEventListener("visibilitychange", onVisibility);
    if (applyTimer !== null) {
      window.clearInterval(applyTimer);
      applyTimer = null;
    }
  };
}

/** The in-flight background download, for tests that must await it. */
export function __backgroundDownloadForTests(): Promise<void> {
  return backgroundDownload ?? Promise.resolve();
}

// ── Did the install we launched actually take? ────────────────────────────
//
// On Windows the plugin hands the NSIS installer to the shell with `/P
// /UPDATE /R` and then hard-exits the process — it never reports back, so
// anything after `install()` (including an error) never runs there. If the
// installer is blocked (SmartScreen on an unsigned build, an elevation prompt
// nobody sees, a locked exe) the app simply reopens on the old version with no
// explanation. That is the "it downloads but nothing changes" report.
//
// So every install attempt records what it was trying to do, and the next boot
// checks whether it happened: the new shell is running (done), the binary is
// new but this page is old (stale shell cache → repair it), or the binary is
// still the old one (the installer never completed → hand over the installer
// instead of silently retrying forever).

const PENDING_INSTALL_KEY = "dental-canvas:pending-update";

interface PendingInstall {
  /** __APP_VERSION__ of the build that started the install. */
  from: string;
  /** Version it tried to install. */
  to: string;
  at: number;
}

function markPendingInstall(from: string, to: string): void {
  try {
    window.localStorage.setItem(PENDING_INSTALL_KEY, JSON.stringify({ from, to, at: Date.now() }));
  } catch {
    /* no storage — verification is skipped for this attempt */
  }
}

function clearPendingInstall(): void {
  try {
    window.localStorage.removeItem(PENDING_INSTALL_KEY);
  } catch {
    /* best effort */
  }
}

function takePendingInstall(): PendingInstall | null {
  try {
    const raw = window.localStorage.getItem(PENDING_INSTALL_KEY);
    if (!raw) return null;
    window.localStorage.removeItem(PENDING_INSTALL_KEY);
    const parsed = JSON.parse(raw) as Partial<PendingInstall>;
    if (!parsed.from || !parsed.to) return null;
    return { from: parsed.from, to: parsed.to, at: Number(parsed.at) || 0 };
  } catch {
    return null;
  }
}

function isWindows(): boolean {
  return typeof navigator !== "undefined" && /Windows/i.test(navigator.userAgent);
}

/**
 * Run once at boot on desktop (see app.tsx). Decides what happened to the
 * update the previous run launched, and recovers from both silent outcomes.
 *
 * No-op when no install was pending, or when the running UI is already the
 * version that was being installed.
 */
export async function verifyUpdateOnBoot(): Promise<void> {
  if (!isUpdateSupported()) return;
  const pending = takePendingInstall();
  if (!pending) return;
  // The new build is loaded — the update applied. The post-update banner
  // (update-applied-banner) takes it from here.
  if (__APP_VERSION__ === pending.to) return;

  let binaryStillOld = false;
  try {
    // The plugin compares the *binary's* version with the feed. A newer signed
    // release still on offer means the exe was never replaced.
    binaryStillOld = Boolean(await check({ timeout: 15_000 }));
  } catch (err) {
    // Offline or the endpoint is unreachable: we cannot tell, so keep the
    // marker and decide on the next launch instead of guessing.
    markPendingInstall(pending.from, pending.to);
    emitDiagnostics({ lastError: `could not verify the last update: ${errorMessage(err)}` });
    return;
  }

  if (binaryStillOld) {
    const feed = await fetchFeed();
    emit({
      version: pending.to,
      notes: (feed?.body ?? "").trim(),
      phase: "available",
      progress: 0,
      mode: "manual",
      downloadUrl: feed ? pickDownloadUrl(feed as Feed) : RELEASES_PAGE,
    });
    emitDiagnostics({
      lastCheckedAt: Date.now(),
      lastError:
        "The last update downloaded but the installer did not finish, so the app is still on the previous version. Download the installer once to complete it.",
      feedVersion: (feed?.tag_name ?? "").replace(/^v/i, "") || pending.to,
      selfInstall: false,
    });
    return;
  }

  // The binary is current but this page still runs the old build: the app
  // shell came from the previous release's cache. Clear it and reload into the
  // installed UI (once per session, so a failing purge cannot loop).
  try {
    if (sessionStorage.getItem("dental-canvas:auto-repaired") === "1") return;
    sessionStorage.setItem("dental-canvas:auto-repaired", "1");
  } catch {
    return;
  }
  emitDiagnostics({
    lastCheckedAt: Date.now(),
    lastError: "The update was installed, but this window was still running the previous shell — clearing the cache.",
    selfInstall: true,
  });
  await repairCachedAppFiles();
}

/**
 * Download and install the pending update via the signed in-app updater, then
 * relaunch. The returned promise resolves when the installer has been launched
 * — on Windows the app is killed by the installer at that point.
 */
export async function installUpdate(): Promise<void> {
  if (!isUpdateSupported()) return;
  const current = state;
  if (!current) return;
  if (current.mode === "repair") {
    await repairCachedAppFiles();
    return;
  }
  if (current.mode === "manual") {
    await openManualUpdate();
    return;
  }
  // Already downloaded in the background: install that copy instead of
  // fetching a second one.
  if (await installStagedUpdate()) return;
  emit({ ...current, phase: "downloading", progress: 0 });
  // Re-check to obtain a fresh Update handle (handles are single-use).
  const update = await check({ timeout: 15_000 });
  if (!update) {
    emit(null);
    emitDiagnostics({ lastError: "the update feed no longer offers this version" });
    return;
  }
  // Download, then install through the same verified path as a staged update:
  // that is what flushes the database to disk and records the attempt before
  // Windows terminates the process. `downloadAndInstall` would do both in one
  // go, which leaves no chance to flush or to notice a silent failure.
  let total = 0;
  await update.download((event) => {
    switch (event.event) {
      case "Started":
        total = event.data.contentLength ?? 0;
        break;
      case "Progress":
        if (total > 0) {
          emit({
            ...state!,
            phase: "downloading",
            progress: Math.min(0.99, (state!.progress * total + event.data.chunkLength) / total),
          });
        }
        break;
      case "Finished":
        break;
    }
  });
  staged = update;
  emit({ version: update.version, notes: current.notes, phase: "staged", progress: 1, mode: "installer" });
  await installStagedUpdate();
}

/** Open the installer for a machine that cannot self-install. */
export async function openManualUpdate(): Promise<void> {
  const url = state?.downloadUrl ?? RELEASES_PAGE;
  await openExternalUrl(url);
}

/**
 * Throw away the cached app shell and service worker, then reload.
 *
 * This is the in-app version of the "stale UI" recovery: if the binary has
 * been updated but the page is still served from an old service-worker cache,
 * the UI keeps reporting the old version and the updater never offers
 * anything again. Only HTTP caches and worker registrations are touched —
 * the clinic database lives in IndexedDB, which is deliberately left alone.
 */
export async function repairCachedAppFiles(): Promise<void> {
  flushDatabase();
  try {
    if ("serviceWorker" in navigator) {
      const registrations = await navigator.serviceWorker.getRegistrations();
      await Promise.all(registrations.map((r) => r.unregister().catch(() => false)));
    }
  } catch {
    // nothing registered — fine
  }
  try {
    const keys = await caches.keys();
    await Promise.all(keys.map((k) => caches.delete(k).catch(() => false)));
  } catch {
    // no Cache Storage — fine
  }
  window.location.reload();
}

/** Hourly re-check; the clinic leaves the app open all day. */
const CHECK_INTERVAL_MS = 60 * 60 * 1000;

/**
 * Start the background update poller. Mount once from the app shell
 * (desktop only); returns a cleanup function.
 */
export function startUpdatePoller(): () => void {
  if (!isUpdateSupported()) return () => undefined;
  const stopWatching = watchForSafeMoment();
  // Give the app time to boot and the clinic a moment before the first probe.
  const initial = window.setTimeout(() => {
    void checkForUpdates();
    checkTimer = window.setInterval(() => void checkForUpdates(), CHECK_INTERVAL_MS);
  }, 60_000);
  return () => {
    window.clearTimeout(initial);
    if (checkTimer !== null) window.clearInterval(checkTimer);
    stopWatching();
  };
}

/** Reset module state for tests. */
export function __resetUpdateStateForTests(): void {
  listeners = new Set();
  diagnosticsListeners = new Set();
  state = null;
  diagnostics = { lastCheckedAt: null, lastError: null, feedVersion: null, selfInstall: true };
  checking = null;
  staged = null;
  backgroundDownload = null;
  updateMode = "ask";
  lastInteractionAt = Date.now();
  hiddenSince = null;
  if (checkTimer !== null) {
    window.clearInterval(checkTimer);
    checkTimer = null;
  }
}
